import{_ as a}from"./chunks/19d892913f88a70cbf47536b9fb10cf3.JrcQ8Gbe.js";import{_ as e,c as n,a2 as o,o as r}from"./chunks/framework.BnrAgU0Y.js";const m=JSON.parse('{"title":"Langflow 中的提示组件","description":"Langflow 中的提示组件","frontmatter":{"title":"Langflow 中的提示组件","description":"Langflow 中的提示组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-prompts.md","filePath":"langflow/components-prompts.md"}'),s={name:"langflow/components-prompts.md"};function p(d,t,i,l,h,c){return r(),n("div",null,t[0]||(t[0]=[o('<h1 id="langflow-中的提示组件" tabindex="-1">Langflow 中的提示组件 <a class="header-anchor" href="#langflow-中的提示组件" aria-label="Permalink to &quot;Langflow 中的提示组件&quot;">​</a></h1><p>提示（Prompt）是输入给语言模型的结构化信息，用于指导模型如何处理用户输入和变量。</p><p>提示组件用于创建具有自定义字段和动态变量的提示模板，以便为您的模型提供结构化、可重复的提示。</p><p>提示是由自然语言和用大括号 <code>{}</code> 创建的变量组合而成的。</p><h2 id="在流程中使用提示组件" tabindex="-1">在流程中使用提示组件 <a class="header-anchor" href="#在流程中使用提示组件" aria-label="Permalink to &quot;在流程中使用提示组件&quot;">​</a></h2><p>在 <a href="/get-started-quickstart#run-the-chatbot-with-retrieved-context">快速入门</a> 中可以找到修改提示的示例，其中一个基础的聊天机器人流程被扩展为包含完整的向量 RAG（检索增强生成）管道。</p><p><img src="'+a+`" alt=""></p><p><strong>Prompt</strong>组件中的默认提示是<code>将用户理解为GenAI专家，热情地帮助他们开始构建一些新的东西。</code></p><p>该提示为您的LLM（大语言模型）的聊天互动创建了一个“个性”，但它不包括在模板化提示时可能有用的变量。</p><p>要修改提示模板，在<strong>Prompt</strong>组件中，点击<strong>Template</strong>字段。例如，<code>{context}</code>变量使LLM模型可以访问嵌入的向量数据，从而提供更好的答案。</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Given the context</span></span>
<span class="line"><span>{context}</span></span>
<span class="line"><span>Answer the question</span></span>
<span class="line"><span>{user_question}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>当变量被添加到提示模板时，组件中会自动创建新的字段。这些字段可以连接以接收其他组件的文本输入，从而实现提示的自动化，或输出给其他组件指令。控制代理行为的提示示例可以在<a href="/tutorials-sequential-agent">顺序任务代理入门流程</a>中找到。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>template</td><td>Template</td><td>创建一个带有动态变量的提示模板。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>prompt</td><td>Prompt Message</td><td>由 <code>build_prompt</code> 方法返回的构建提示信息。</td></tr></tbody></table><h2 id="langchain-hub-提示模板" tabindex="-1">Langchain Hub 提示模板 <a class="header-anchor" href="#langchain-hub-提示模板" aria-label="Permalink to &quot;Langchain Hub 提示模板&quot;">​</a></h2><p>该组件从 <a href="https://docs.smith.langchain.com/old/category/prompt-hub" target="_blank" rel="noreferrer">Langchain Hub</a> 获取提示。</p><p>当加载一个提示时，组件会为自定义变量生成输入字段。例如，默认提示 &quot;efriis/my-first-prompt&quot; 会生成 <code>profession</code> 和 <code>question</code> 的字段。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>langchain_api_key</td><td>Your LangChain API Key</td><td>您的 LangChain API 密钥</td></tr><tr><td>langchain_hub_prompt</td><td>LangChain Hub Prompt</td><td>要使用的 LangChain Hub 提示</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>prompt</td><td>构建提示</td><td>由 \`build_prompt\` 方法返回的构建提示消息。</td></tr></tbody></table>`,23)]))}const g=e(s,[["render",p]]);export{m as __pageData,g as default};
